def dehydrate_timedelta(value):
    if not isinstance(value, timedelta):
        raise ValueError("Input must be a timedelta object")
    return value.total_seconds()

def dehydrate_time(value):
    if not isinstance(value, time):
        raise ValueError("Input must be a time object")
    return value.strftime("%Y-%m-%d %H:%M:%S")

def dehydrate_point(value):
    if not isinstance(value, Point):
        raise ValueError("Input must be an instance of Point")
    return {
        "x": value.x,
        "y": value.y
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if not self._data:
        raise ValueError("Record is empty")
    return list(self._data.keys())

def protocol_handlers(cls, protocol_version=None):
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if protocol_version not in cls._supported_protocols:
        raise ValueError("Unsupported protocol version")
    return {protocol_version: cls._supported_protocols[protocol_version]}

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if timeout is not None:
                start_time = time.time()
                try:
                    result = func(*args, **kwargs)
                    end_time = time.time()
                    if end_time - start_time > timeout:
                        raise TimeoutError(f"Transaction timed out after {timeout} seconds")
                except Exception as e:
                    if timeout is not None:
                        print(f"Transaction timed out after {timeout} seconds")
                    raise e
            else:
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

def index(self, key):
    if not isinstance(key, int):
        raise ValueError("Key must be an integer")
    if key < 0 or key >= len(self.data):
        raise IndexError("Key is out of range")
    return self.data.index(key)

def values(self, *keys):
    if not keys:
        return list(self._data.values())
    return [self._data[key] for key in keys if key in self._data]

def data(self, *keys):
    if not keys:
        return {key: getattr(self, key) for key in dir(self) if not key.startswith('__')}
    else:
        return {key: getattr(self, key) for key in keys if hasattr(self, key)}

def pop_u16(self):
    if not self.data or len(self.data) < 2:
        raise ValueError("Data is too short to pop a 16-bit unsigned integer")
    return int.from_bytes(self.data[-2:], byteorder='big', signed=False)

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    if n < 0:
        n = -1  # Default to discard all records
    if qid < 0:
        qid = -1  # Default to last query

    # Create a DISCARD message
    discard_message = {
        'type': 'DISCARD',
        'n': n,
        'qid': qid
    }

    # Apply dehydration hooks if provided
    if dehydration_hooks:
        for key, value in discard_message.items():
            if key in dehydration_hooks:
                discard_message[key] = dehydration_hooks[key](value)

    # Apply hydration hooks if provided
    if hydration_hooks:
        for key, value in discard_message.items():
            if key in hydration_hooks:
                discard_message[key] = hydration_hooks[key](value)

    # Append the message to the output queue
    self.output_queue.append(discard_message)

    # Return the response object with handlers
    return Response(discard_message, handlers)

def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or a float")
    if n == int(n):
        return n
    if n % 1 == 0.5:
        return int(n + 0.5) if n > 0 else int(n - 0.5)
    return round(n)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            if len(args) != len(fields):
                raise ValueError("Number of arguments does not match the number of fields")
            for field, value in zip(fields, args):
                setattr(self, field, value)
            if 'srid' in kwargs:
                self.srid = kwargs['srid']
            else:
                self.srid = srid_map.get(name, 0)

    return Point

