def _shuffled(seq: Sequence[str]) -> list[str]:
    if not seq:
        return []
    shuffled_seq = list(seq)
    random.shuffle(shuffled_seq)
    return shuffled_seq

def parse_version(s: str) -> tuple[int, ...]:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s:
        raise ValueError("Input string cannot be empty")
    parts = s.split('.')
    if len(parts) != 3:
        raise ValueError("Input string must contain exactly three parts separated by dots")
    try:
        return tuple(int(part) for part in parts)
    except ValueError:
        raise ValueError("Invalid version part")

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    # Check if the command is a tuple of strings
    if not all(isinstance(item, str) for item in cmd):
        raise ValueError("Command must be a tuple of strings")

    # Check if the command is a shebang
    if cmd[0].startswith('#!'):
        # Remove the shebang
        cmd = cmd[1:]

    # Check if the command is a deep-path shebang
    if cmd[0].startswith('/'):
        # Remove the leading slash
        cmd = cmd[1:]

    return cmd

def cached(cache, key=hashkey, lock=None):
    def wrapper(func):
        def memoized_func(*args, **kwargs):
            if key is not None:
                key_value = key(*args, **kwargs)
            else:
                key_value = args
            if key_value in cache:
                return cache[key_value]
            else:
                result = func(*args, **kwargs)
                cache[key_value] = result
                return result
        return memoized_func
    return wrapper

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = OrderedDict()
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            if timer() - cache[key][1] > ttl:
                del cache[key]
            else:
                return cache[key][0]
        result = func(*args, **kwargs)
        if len(cache) >= maxsize:
            cache.popitem(last=False)
        cache[key] = (result, timer())
        return result
    return wrapper

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    @lru_cache(maxsize=maxsize, typed=typed)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

