    return self[key]

def cachedmethod(cache, key=hashkey, lock=None):
    if lock is None:
        lock = threading.Lock()

    @functools.wraps(key)
    def wrapper(*args, **kwargs):
        with lock:
            if key(*args, **kwargs) not in cache:
                cache[key(*args, **kwargs)] = key(*args, **kwargs)
            return cache[key(*args, **kwargs)]
    return wrapper

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    try:
        if overwrite:
            with open(file_name, 'w', encoding=encoding) as file:
                file.write(text_buffer)
        else:
            with open(file_name, 'a', encoding=encoding) as file:
                file.write(text_buffer)
        return len(text_buffer)
    except Exception as e:
        print(f"An error occurred: {e}")
        return -1

def file_to_textbuffer(file_name, encoding):
    try:
        with open(file_name, 'r', encoding=encoding) as file:
            text_buffer = file.read()
        return text_buffer
    except FileNotFoundError:
        print(f"File '{file_name}' not found.")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str):
        raise ValueError("File name must be a string")
    if not file_name:
        raise ValueError("File name cannot be empty")
    return os.path.isfile(file_name)

