def is_fill_request_seq(seq):
    if not isinstance(seq, FillRequest):
        return False
    if isinstance(seq, Source):
        return False
    if not any(isinstance(item, FillRequest) for item in seq):
        return False
    return True

def is_fill_request_el(obj):
    if not hasattr(obj, 'fill') or not hasattr(obj, 'request'):
        raise ValueError("Object must contain 'fill' and 'request' methods.")
    return True

def is_run_el(obj):
    if not hasattr(obj, 'run'):
        raise ValueError("Object does not contain an executable method 'run'")
    try:
        obj.run()
        return True
    except Exception as e:
        print(f"Error running the method: {e}")
        return False

def is_fill_compute_el(obj):
    if not hasattr(obj, 'fill') or not hasattr(obj, 'compute'):
        raise ValueError("Object must contain executable methods 'fill' and 'compute'")
    if not callable(obj.fill) or not callable(obj.compute):
        raise ValueError("Methods 'fill' and 'compute' must be callable")
    return True

def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    elif level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict) and isinstance(d2.get(k), dict):
                result[k] = difference(v, d2[k], level - 1)
        return result

def fill(self, coord, weight=1):
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Invalid coordinate format. Expected a tuple of two integers.")
    if not isinstance(weight, (int, float)):
        raise ValueError("Invalid weight type. Expected an integer or float.")
    if not self.is_valid_coord(coord):
        raise ValueError("Coordinate is out of the histogram edges.")
    self.histogram[coord] += weight

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("Input must be a dictionary")
    if not isinstance(first_level, bool):
        raise ValueError("first_level must be a boolean")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, list):
            observer_schema[key] = [None] * len(value)
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level)
        else:
            observer_schema[key] = None

    if first_level:
        # Copy identifying fields from the manifest file
        observer_schema['apiVersion'] = manifest_dict.get('apiVersion')
        observer_schema['kind'] = manifest_dict.get('kind')
        observer_schema['metadata'] = manifest_dict.get('metadata', {})

    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest.append(field)

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(params, (dict, list)):
        raise TypeError("params must be a dict or list")
    if self.SQLParams.in_style == "named":
        if not isinstance(params, dict):
            raise TypeError("params must be a dict if SQLParams.in_style is named")
    elif self.SQLParams.in_style == "ordinal":
        if not isinstance(params, list):
            raise TypeError("params must be a list if SQLParams.in_style is ordinal")
    else:
        raise ValueError("SQLParams.in_style must be 'named' or 'ordinal'")
    formatted_sql = sql.replace("?", "%s")
    converted_params = params
    return formatted_sql, converted_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(many_params, (Iterable,)):
        raise TypeError("many_params must be an iterable")

    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if isinstance(params, dict):
            if self.SQLParams.in_style == 'named':
                if not all(isinstance(key, str) for key in params):
                    raise ValueError("named parameters must be strings")
                if not all(isinstance(value, (int, float, str, bytes)) for value in params.values()):
                    raise ValueError("named parameters must be integers, floats, strings, or bytes")
            elif self.SQLParams.in_style == 'ordinal':
                if not all(isinstance(value, (int, float)) for value in params.values()):
                    raise ValueError("ordinal parameters must be integers or floats")
            else:
                raise ValueError("invalid in_style")
        elif isinstance(params, (list, tuple)):
            if self.SQLParams.in_style == 'named':
                if not all(isinstance(item, str) for item in params):
                    raise ValueError("named parameters must be strings")
                if not all(isinstance(value, (int, float, str, bytes)) for value in params):
                    raise ValueError("named parameters must be integers, floats, strings, or bytes")
            elif self.SQLParams.in_style == 'ordinal':
                if not all(isinstance(value, (int, float)) for value in params):
                    raise ValueError("ordinal parameters must be integers or floats")
            else:
                raise ValueError("invalid in_style")
        else:
            raise TypeError("params must be a dict or a list/tuple")

        converted_params.append(params)

    return formatted_sql, converted_params

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string")
    if not isinstance(self, Validator):
        raise ValueError("Validator object is required")
    return f"{prefix}{self.status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise ValueError("Prefix must be a string")
    if not isinstance(self, ValidationLog):
        raise ValueError("self must be an instance of ValidationLog")
    return f"{prefix}{self.log}"

def validate(self, inventory, extract_spec_version=False):
    if not inventory:
        raise ValueError("Inventory cannot be empty")
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")
    if extract_spec_version:
        if 'type' not in inventory:
            raise KeyError("Inventory must contain a 'type' key")
        if inventory['type'] not in self.spec_version:
            raise ValueError(f"Invalid type '{inventory['type']}' in inventory")
    else:
        if 'version' not in inventory:
            raise KeyError("Inventory must contain a 'version' key")
        if inventory['version'] not in self.spec_version:
            raise ValueError(f"Invalid version '{inventory['version']}' in inventory")

def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, list) or not all(isinstance(file, str) for file in manifest_files):
        raise ValueError("Manifest files must be a list of strings.")
