        command = [func.__module__, func.__name__] + list(args)

        # Set the environment variables if provided
        if extra_env:
            command.extend(['--env', f'{key}={value}' for key, value in extra_env.items()])

        # Run the subprocess
        result = subprocess.run(command, timeout=timeout, check=True, capture_output=True, text=True)

        # Return the output of the subprocess
        return result.stdout
    except subprocess.TimeoutExpired:
        return f"Timeout expired after {timeout} seconds"
