def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not graph or not prop:
        raise ValueError("Graph and property must be provided")

    if roots is None:
        roots = set()

    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for child in graph.objects(node, prop):
            dfs(child)

    for node in graph.subjects(prop, None):
        dfs(node)

    return roots

