def identify_request(request: RequestType):
    if not isinstance(request, RequestType):
        raise ValueError("Invalid request type")

    if request.public_message:
        return "Diaspora public message"
    elif request.private_message:
        return "Diaspora private message"
    elif request.legacy_payload:
        return "Legacy Diaspora payload"
    else:
        return "Unknown Diaspora request type"

def identify_request(request: RequestType) -> bool:
    if not isinstance(request, RequestType):
        raise ValueError("Invalid request type")
    if request.method == "POST" and request.url.startswith("/matrix"):
        return True
    return False

def format_dt(dt):
    if not isinstance(dt, datetime):
        raise ValueError("Input must be a datetime object")
    if dt.year < 1900 or dt.year > 2100:
        raise ValueError("Year must be between 1900 and 2100")
    if dt.month < 1 or dt.month > 12:
        raise ValueError("Month must be between 1 and 12")
    if dt.day < 1 or dt.day > 31:
        raise ValueError("Day must be between 1 and 31")
    return dt.strftime("%Y-%m-%d")

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    current_tag = None

    for char in text:
        if char == '<':
            in_code_block = True
            current_tag = None
        elif char == '>':
            in_code_block = False
            if current_tag:
                tags.add(current_tag)
                if replacer:
                    current_tag = replacer(current_tag)
        elif not in_code_block:
            if char == '[':
                current_tag = ''
            elif current_tag and char == ']':
                current_tag += char
            elif current_tag:
                current_tag += char

    return tags, text

def fetch_content_type(url: str) -> Optional[str]:
    try:
        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('content-type')
        else:
            return None
    except requests.RequestException as e:
        print(f"Error fetching content type: {e}")
        return None

def test_tag(tag: str) -> bool:
    if not isinstance(tag, str):
        raise ValueError("Input must be a string")
    if len(tag) < 2 or len(tag) > 20:
        raise ValueError("Tag length must be between 2 and 20 characters")
    if not tag.isalnum():
        raise ValueError("Tag must contain only alphanumeric characters")
    return True

def xml_children_as_dict(node):
    if not node:
        return {}
    children = node.getchildren()
    if not children:
        return {}
    result = {}
    for child in children:
        result[child.tag] = child.text
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender and entity handles must be provided.")
    if sender_handle != entity_handle:
        raise ValueError("Sender and entity handles do not match.")

