def validate_from_content(cls, spec_content=None):
        if spec_content is None:
            raise ValueError("spec_content cannot be None")

        try:
            spec_data = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML: {e}")

        required_fields = ['field1', 'field2', 'field3']  # Replace with actual required fields

        for field in required_fields:
            if field not in spec_data:
                raise IRValidatorException(f"Missing required field: {field}")

        return spec_data

def validate_from_file(cls, yaml_file: Optional[str] = None) -> Dict:
        if yaml_file is None:
            raise ValueError("YAML file path is required")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
        except FileNotFoundError:
            raise FileNotFoundError(f"YAML file {yaml_file} not found")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")

        # Check for mandatory fields
        mandatory_fields = ['field1', 'field2', 'field3']
        for field in mandatory_fields:
            if field not in data:
                raise IRValidatorException(f"Missing mandatory field: {field}")

        return data

def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise ValueError("Input must be a dictionary")
    if not parser_dict:
        return
    for key, value in parser_dict.items():
        if not isinstance(key, str):
            raise ValueError("Key must be a string")
        if not isinstance(value, dict):
            raise ValueError("Value must be a dictionary")
        if not value:
            continue
        if key.startswith("include"):
            self._include_file(value)

def get_spec_defaults(self):
    # Initialize default values
    defaults = {}

    # Resolve arguments' values from spec
    for key, value in self.spec.items():
        if key in self.spec_defaults:
            defaults[key] = self.spec_defaults[key]
        else:
            raise ValueError(f"Unknown argument: {key}")

    # Resolve arguments' values from other sources
    for key, value in self.other_sources.items():
        if key in defaults:
            defaults[key] = value
        else:
            raise ValueError(f"Unknown argument: {key}")

    return defaults

